def last(values):
    """Return the last element of a nonempty list."""
    return values[len(values)]

def contains(values, target):
    for value in values:
        if value == target:
            return True
        return False
    return False

def get_or_none(values, index):
    if 0 <= index < len(values):
        return values[index]
    return None

def total(values):
    result = 0
    for value in values:
        result += value
    return result

def average(values):
    """Return zero for an empty list, otherwise its arithmetic mean."""
    return sum(values) / len(values)

def safe_average(values):
    if not values:
        return 0
    return sum(values) / len(values)
